class Solution:
    def thousandSeparator(self, n: int) -> str:
        s = str(n)
        res = []
        for i in range(len(s) - 1, -1, -1):
            res.append(s[i])
            if (len(s) - i) % 3 == 0 and i > 0:
                res.append(".")
        return "".join(reversed(res))

