class Solution:
    def thousandSeparator(self, n: int) -> str:
        if n == 0:
            return "0"
        parts = []
        while n:
            parts.append(str(n % 1000))
            n //= 1000
        out = parts[-1]
        for p in reversed(parts[:-1]):
            out += "." + p.zfill(3)
        return out

