class Solution {
public:
    string thousandSeparator(int n) {
        if (n == 0) return "0";
        vector<string> parts;
        while (n > 0) {
            parts.push_back(to_string(n % 1000));
            n /= 1000;
        }
        string res = parts.back();
        for (int i = (int)parts.size() - 2; i >= 0; --i) {
            const string& p = parts[i];
            res += '.' + string(3 - p.size(), '0') + p;
        }
        return res;
    }
};

