class Solution {
    public String thousandSeparator(int n) {
        if (n == 0) return "0";
        Deque<String> parts = new ArrayDeque<>();
        while (n > 0) {
            parts.push(Integer.toString(n % 1000));
            n /= 1000;
        }
        StringBuilder sb = new StringBuilder(parts.pop());
        while (!parts.isEmpty()) {
            String p = parts.pop();
            sb.append('.');
            for (int i = p.length(); i < 3; i++) sb.append('0');
            sb.append(p);
        }
        return sb.toString();
    }
}

