var thousandSeparator = function(n) {
    if (n === 0) return "0";
    const parts = [];
    while (n > 0) {
        parts.push(String(n % 1000));
        n = Math.floor(n / 1000);
    }
    let res = parts.pop();
    while (parts.length) {
        res += "." + parts.pop().padStart(3, "0");
    }
    return res;
};
